-- Valoir — Postgres / Supabase schema
-- Run once in Supabase → SQL Editor (safe to re-run: it drops and recreates the app tables).
--
-- Design
-- * Every row belongs to one user: primary key (user_id, id). Default ids such as
--   "c-food" exist for every user, so ids only need to be unique per user.
-- * user_id defaults to auth.uid() and Row Level Security only ever exposes the
--   caller's own rows — even a buggy API call cannot read or write someone else's data.
-- * Ids are generated by the app (text), so offline edits and imports keep their ids.
-- * Nested parts that are always read/written with their parent (transport legs,
--   spend plan items, per-category budget limits) are jsonb on the parent row.
-- * Money is VND: whole numbers in bigint.

drop table if exists public.spend_plans cascade;
drop table if exists public.transport_entries cascade;
drop table if exists public.transport_meters cascade;
drop table if exists public.month_plans cascade;
drop table if exists public.recurring_rules cascade;
drop table if exists public.budgets cascade;
drop table if exists public.transactions cascade;
drop table if exists public.categories cascade;

create table public.categories (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null,
  icon text not null default '',
  color text not null default '',
  type text not null check (type in ('expense', 'income')),
  sort_order int not null default 0,
  is_archived boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.transactions (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  category_id text not null,
  amount bigint not null check (amount > 0),
  type text not null check (type in ('expense', 'income')),
  date date not null,
  note text,
  recurring_rule_id text,
  plan_id text,
  transport_meter_id text,
  spend_plan_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

create index transactions_user_date_idx on public.transactions (user_id, date desc);

-- One budget per month; `categories` = [{ "categoryId": "...", "limitAmount": 3000000 }]
create table public.budgets (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  year_month char(7) not null check (year_month ~ '^\d{4}-\d{2}$'),
  note text,
  categories jsonb not null default '[]',
  updated_at timestamptz not null default now(),
  primary key (user_id, year_month)
);

create table public.recurring_rules (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null,
  category_id text not null,
  amount bigint not null check (amount > 0),
  type text not null check (type in ('expense', 'income')),
  day_of_month int not null check (day_of_month between 1 and 28),
  start_month char(7) not null,
  end_month char(7),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.month_plans (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  title text not null,
  note text,
  amount bigint not null check (amount > 0),
  category_id text not null,
  type text not null check (type in ('expense', 'income')),
  target_month char(7) not null,
  day_of_month int not null check (day_of_month between 1 and 28),
  is_posted boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.transport_meters (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null,
  icon text not null default '',
  sort_order int not null default 0,
  is_archived boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

-- `legs` = [{ "id": "...", "from": "Home", "to": "Office", "amount": 45000 }]
create table public.transport_entries (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  meter_id text not null,
  date date not null,
  amount bigint not null check (amount >= 0),
  legs jsonb not null default '[]',
  transaction_id text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

-- `items` = [{ "id", "name", "categoryId", "estimate", "actual" (null = not filled), "isExtra" }]
create table public.spend_plans (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  title text not null,
  icon text not null default '',
  start_date date not null,
  end_date date,
  note text,
  items jsonb not null default '[]',
  status text not null default 'planning' check (status in ('planning', 'done')),
  posted_count int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id),
  constraint spend_plan_dates check (end_date is null or end_date >= start_date)
);

-- Row Level Security: each signed-in user sees and changes only their own rows.
do $$
declare
  t text;
begin
  foreach t in array array[
    'categories', 'transactions', 'budgets', 'recurring_rules',
    'month_plans', 'transport_meters', 'transport_entries', 'spend_plans'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format(
      'create policy "own rows" on public.%I for all to authenticated
         using (user_id = (select auth.uid()))
         with check (user_id = (select auth.uid()))',
      t
    );
  end loop;
end $$;
